import { defineConfig, type PlaywrightTestConfig } from '@playwright/test';

/**
 * Visual regression suite (`e2e/visual.spec.ts`).
 *
 * Screenshots are pixel-compared against committed baselines. Font rasterising
 * differs between macOS and Linux, so baselines are per platform and only the
 * Linux set — generated by the CI "Visual regression" job — is committed.
 * Local darwin baselines are git-ignored (see e2e/.gitignore) and exist only as
 * a convenience for `npm run test:visual`.
 *
 * Everything that could make two runs differ is pinned here or in the spec:
 * viewport, colour scheme, reduced motion, timezone, locale, the wall clock
 * (spec), the tour flag (spec), service workers, and external network (spec).
 */
const PORT = 4173;
const BASE_URL = `http://127.0.0.1:${PORT}`;

type Use = NonNullable<PlaywrightTestConfig['use']>;

const desktop: Use = {
  viewport: { width: 1440, height: 900 },
  deviceScaleFactor: 1,
  isMobile: false,
  hasTouch: false,
};

const mobile: Use = {
  viewport: { width: 390, height: 844 },
  // 1x keeps the committed PNGs small; the job is catching regressions, not
  // reproducing a Retina screen.
  deviceScaleFactor: 1,
  isMobile: true,
  hasTouch: true,
};

export default defineConfig({
  testDir: './e2e',
  testMatch: /.*\.spec\.ts$/,
  outputDir: './e2e/.results',
  snapshotPathTemplate: '{testDir}/__screenshots__/{testFilePath}/{arg}-{projectName}-{platform}{ext}',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: 0,
  // Each test creates a vault (PBKDF2) and seeds the sample; two workers keep
  // that within the sandbox's process budget locally and on CI runners.
  workers: 2,
  timeout: 90_000,
  expect: {
    timeout: 15_000,
    toHaveScreenshot: {
      // A fixed pixel budget, not a ratio: 0.2% of a tall page is ~9,700 px, enough
      // to hide a chip losing its fill (~1,200 px). Renders are identical run to
      // run under the frozen clock, so a tight budget does not flake.
      maxDiffPixels: 100,
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
    },
  },
  reporter: process.env.CI
    ? [['list'], ['html', { outputFolder: './e2e/.report', open: 'never' }], ['github']]
    : [['list'], ['html', { outputFolder: './e2e/.report', open: 'never' }]],
  use: {
    baseURL: BASE_URL,
    locale: 'en-IN',
    timezoneId: 'Asia/Kolkata',
    reducedMotion: 'reduce',
    serviceWorkers: 'block',
    trace: 'retain-on-failure',
  },
  projects: [
    { name: 'desktop-light', use: { ...desktop, colorScheme: 'light' } },
    { name: 'desktop-dark', use: { ...desktop, colorScheme: 'dark' } },
    { name: 'mobile-light', use: { ...mobile, colorScheme: 'light' } },
    { name: 'mobile-dark', use: { ...mobile, colorScheme: 'dark' } },
  ],
  // Serves the static export; run `npm run build` first.
  webServer: {
    command: `node e2e/serve-out.mjs ${PORT}`,
    url: `${BASE_URL}/dashboard/`,
    reuseExistingServer: !process.env.CI,
    timeout: 30_000,
  },
});
